import { test, expect } from "../helpers/system-control-browser";
import { PLAN_COMPARISON_ROWS } from "../../src/lib/plan-features";
import AxeBuilder from "@axe-core/playwright";

test("pricing preserves enforced limits, account entry points and fine print", async ({
  page,
}) => {
  await page.goto("/pricing");
  const main = page.getByRole("main");
  await expect(page).toHaveTitle("Plans and pricing | Mailloop");
  await expect(main.getByRole("heading", { level: 1 })).toHaveText(
    "Simple pricing for serious outreach.",
  );
  await expect(page.locator("[data-localized-price]")).toHaveText("$5.99");
  const free = page.getByRole("article", { name: "Free plan", exact: true });
  await expect(
    free.getByRole("button", { name: "Start free", exact: true }),
  ).toBeVisible();
  await expect(
    page.getByRole("button", { name: "Upgrade to Premium", exact: true }),
  ).toBeEnabled();
  await expect(
    page.getByRole("link", { name: /See every feature/ }),
  ).toHaveCount(0);
  await expect(free).toContainText("no card needed");
  await expect(free).toContainText("2 saved role shortcuts");
  await expect(free.locator("li")).toHaveCount(5);
  await expect(
    page
      .getByRole("article", { name: "Premium plan", exact: true })
      .locator("li"),
  ).toHaveCount(10);
  const premiumCard = page.getByRole("article", {
    name: "Premium plan",
    exact: true,
  });
  await expect(premiumCard.getByLabel("per month, tax included")).toHaveText(
    "/ month · tax included",
  );
  await expect(premiumCard).toContainText(
    "Add to shortlist directly from History",
  );
  await expect(premiumCard.getByRole("heading", { level: 3 })).toHaveCount(0);
  const comparison = page.getByRole("table", {
    name: "Free and Premium plan comparison",
  });
  await expect(comparison).toHaveCount(1);
  await expect(comparison.locator("thead th")).toHaveText([
    "Feature",
    "Free",
    "Premium",
  ]);
  await expect(comparison.locator('th[scope="rowgroup"]')).toHaveText([
    "Sending",
    "Templates and contacts",
    "Tracking",
    "Look and support",
  ]);
  await expect(comparison.locator('th[scope="row"]')).toHaveCount(
    PLAN_COMPARISON_ROWS.length,
  );
  for (const [label, freeValue, premium] of PLAN_COMPARISON_ROWS) {
    const row = comparison.getByRole("row").filter({
      has: page.getByRole("rowheader", { name: label, exact: true }),
    });
    for (const [index, value] of [freeValue, premium].entries()) {
      const cell = row.getByRole("cell").nth(index);
      await expect(cell).toHaveText(
        value === "Unavailable" ? "Not included" : String(value),
      );
      await expect(
        cell.locator(
          value === "Unavailable" ? "svg.lucide-crown" : "svg.lucide-check",
        ),
      ).toHaveAttribute("aria-hidden", "true");
    }
  }
  for (const text of [
    "Billing country determines eligibility",
    "Daily allowances reset at midnight UTC",
    "first day of each UTC calendar month",
    "verified subscription billing period",
    "Unused emails do not roll over.",
    "Queued emails reserve capacity",
    "Manually sent follow-up emails also use allowances",
    "never reads your inbox",
    "cannot detect replies itself",
    "stops reminders for that contact",
    "approve each message",
    "renews monthly",
    "Cancel at period end",
    "No refunds, except where required by applicable law.",
    "Your workspace shows the allowances currently enforced during rollout.",
  ])
    await expect(main).toContainText(text);
  await expect(
    main.getByRole("link", { name: "[REDACTED_EMAIL]" }),
  ).toHaveAttribute("href", "mailto:[REDACTED_EMAIL]");
  const navigation = page.getByRole("navigation", {
    name: "Pages",
    exact: true,
  });
  await expect(navigation.getByRole("link")).toHaveText(["Home", "Pricing"]);
  await expect(
    navigation.getByRole("link", { name: "Home", exact: true }),
  ).toHaveAttribute("href", "/");
  await expect(
    navigation.getByRole("link", { name: "Pricing", exact: true }),
  ).toHaveAttribute("aria-current", "page");
  await expect(page.locator(".pricing-nav .logo")).toHaveText("mailloop");
  await expect(main).not.toContainText("Operated by Czar16.");
  await expect(page.locator(".pricing-shell .pricing-nav")).toHaveCount(0);
});

for (const route of ["/", "/pricing"]) {
  test(`localized pricing on ${route} preserves header precedence`, async ({
    page,
  }) => {
    const price =
      route === "/"
        ? page.locator("#pricing [data-localized-price]")
        : page.locator("[data-localized-price]");
    for (const [headers, query, expected] of [
      [{}, "", "$5.99"],
      [{}, "?country=IN", "₹299"],
      [{ "x-vercel-ip-country": "in" }, "", "₹299"],
      [{ "x-vercel-ip-country": "US" }, "?country=IN", "$5.99"],
      [{ "cf-ipcountry": "IN" }, "", "₹299"],
      [{ "x-vercel-ip-country": "GB", "cf-ipcountry": "IN" }, "", "$5.99"],
    ] as const) {
      await page.setExtraHTTPHeaders(headers);
      await page.goto(`${route}${query}`);
      await expect(price).toContainText(expected);
    }
  });
}

test("pricing is responsive and accessible across all palettes", async ({
  page,
}) => {
  test.setTimeout(120000);
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.goto("/pricing");
  await page.evaluate(() => document.fonts.ready);
  for (const [appearance, theme, name] of [
    ["purple", "light", "lavender"],
    ["purple", "dark", "nightbloom"],
    ["vercel", "light", "chalk"],
    ["vercel", "dark", "obsidian"],
  ]) {
    for (const width of [1440, 820, 700, 699, 390, 320]) {
      await page.setViewportSize({ width, height: 1000 });
      // Palette preview only; account entitlement behavior is tested separately.
      await page.evaluate(
        ({ appearance, theme }) => {
          document.documentElement.dataset.appearance = appearance;
          document.documentElement.dataset.theme = theme;
        },
        { appearance, theme },
      );
      expect(
        await page.evaluate(
          () => document.documentElement.scrollWidth <= innerWidth,
        ),
      ).toBe(true);
      const free = (await page
        .getByRole("article", { name: "Free plan", exact: true })
        .boundingBox())!;
      const premium = (await page
        .getByRole("article", { name: "Premium plan", exact: true })
        .boundingBox())!;
      if (width >= 700) {
        expect(free.y).toBeCloseTo(premium.y, 0);
        expect(free.height).toBeCloseTo(premium.height, 0);
        const freeAction = (await page
          .getByRole("article", { name: "Free plan", exact: true })
          .getByRole("button", { name: "Start free" })
          .boundingBox())!;
        const premiumAction = (await page
          .getByRole("button", { name: "Upgrade to Premium", exact: true })
          .boundingBox())!;
        expect(freeAction.y).toBeCloseTo(premiumAction.y, 0);
      } else expect(free.y).toBeGreaterThan(premium.y + premium.height);
      const scroll = page.getByRole("region", {
        name: "Scrollable plan comparison",
      });
      if (width < 760)
        expect(
          await scroll.evaluate((el) => el.scrollWidth > el.clientWidth),
        ).toBe(true);
      const badges = await page
        .locator("main svg.lucide-check")
        .evaluateAll((els) =>
          els.map((el) => {
            const css = getComputedStyle(el);
            const probe = document.createElement("span");
            probe.style.color = "var(--pricing-check)";
            el.parentElement!.append(probe);
            const fill = getComputedStyle(probe).color;
            probe.remove();
            return {
              solid: css.backgroundColor === fill,
              contrasting: css.color !== css.backgroundColor,
              round: css.borderRadius === "50%",
            };
          }),
        );
      expect(badges.length).toBeGreaterThan(11);
      expect(
        badges.every(
          (badge) => badge.solid && badge.contrasting && badge.round,
        ),
      ).toBe(true);
      if (width < 700) {
        await scroll.focus();
        await page.keyboard.press("ArrowRight");
        await expect
          .poll(() => scroll.evaluate((el) => el.scrollLeft))
          .toBeGreaterThan(0);
        await scroll.evaluate((el) => {
          el.scrollLeft = 0;
        });
      }
      const trigger = page.getByRole("button", { name: "Choose appearance" });
      await trigger.focus();
      await page.keyboard.press("ArrowDown");
      const menu = page.getByRole("menu", { name: "Appearance", exact: true });
      await expect(menu).toBeVisible();
      const menuBounds = (await menu.boundingBox())!;
      expect(menuBounds.x).toBeGreaterThanOrEqual(0);
      expect(menuBounds.x + menuBounds.width).toBeLessThanOrEqual(width);
      await page.keyboard.press("Escape");
      await expect(trigger).toBeFocused();
      await trigger.blur();
      await page.evaluate(() => window.scrollTo(0, 0));
      const results = await new AxeBuilder({ page }).analyze();
      expect(results.violations).toEqual([]);
      await page.screenshot({
        path: test.info().outputPath(`pricing-${name}-${width}.png`),
        fullPage: true,
      });
    }
  }
});

test("original pricing theme menu persists and enforces Premium access", async ({
  page,
}) => {
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.goto("/pricing");
  for (const [name, theme] of [
    ["Lavender Light", "light"],
    ["Nightbloom Dark", "dark"],
  ]) {
    await page.getByRole("button", { name: "Choose appearance" }).click();
    await page.getByRole("menuitemradio", { name, exact: true }).click();
    await page.reload();
    await expect(page.locator("html")).toHaveAttribute("data-theme", theme);
  }
  for (const name of ["Chalk Premium Light", "Obsidian Premium Dark"]) {
    await page.getByRole("button", { name: "Choose appearance" }).click();
    const locked = page.getByRole("menuitemradio", { name, exact: true });
    await expect(locked).toBeEnabled();
    await locked.click();
    const dialog = page.getByRole("dialog", {
      name: "Upgrade to Premium",
      exact: true,
    });
    await expect(dialog).toBeVisible();
    await expect(dialog.locator('[data-highlighted="true"]')).toHaveAttribute(
      "data-upgrade-feature",
      "themes",
    );
    await expect(page.locator("html")).toHaveAttribute(
      "data-appearance",
      "purple",
    );
    await page.keyboard.press("Escape");
    await expect(dialog).toHaveCount(0);
  }
  await expect(
    page.getByRole("button", { name: "Choose appearance" }),
  ).toBeFocused();
  const scroll = page.getByRole("region", {
    name: "Scrollable plan comparison",
  });
  await scroll.focus();
  expect(
    await scroll.evaluate((el) => [
      getComputedStyle(el).outlineStyle,
      getComputedStyle(el).outlineWidth,
      getComputedStyle(el).outlineOffset,
    ]),
  ).toEqual(["solid", "2px", "2px"]);
  expect(
    await scroll.evaluate((el) => getComputedStyle(el).transitionDuration),
  ).toBe("0s");
  await page.emulateMedia({ reducedMotion: "no-preference" });
  expect(
    await scroll.evaluate((el) => getComputedStyle(el).transitionDuration),
  ).toBe("0.25s, 0.25s, 0.25s");
});

test("pricing retains app typography and button hover feedback", async ({
  page,
  isMobile,
}) => {
  const landing = [];
  for (const width of [1440, 390]) {
    await page.setViewportSize({ width, height: 1000 });
    await page.goto("/");
    await page.getByRole("heading", { level: 1 }).waitFor();
    landing.push(
      await page.locator(".landing-logo").evaluate((el) => ({
        x: el.getBoundingClientRect().x,
        font: getComputedStyle(el).fontFamily,
        size: getComputedStyle(el).fontSize,
        background: getComputedStyle(document.querySelector(".landing")!)
          .backgroundColor,
      })),
    );
  }
  for (const [index, width] of [1440, 390].entries()) {
    await page.setViewportSize({ width, height: 1000 });
    await page.goto("/pricing");
    await page.getByRole("heading", { level: 1 }).waitFor();
    const logo = await page.locator(".pricing-nav .logo").evaluate((el) => ({
      x: el.getBoundingClientRect().x,
      font: getComputedStyle(el).fontFamily,
      size: getComputedStyle(el).fontSize,
      background: getComputedStyle(document.querySelector(".pricing-page")!)
        .backgroundColor,
    }));
    expect(logo.font).toBe(landing[index].font);
    expect(logo.background).toBe(landing[index].background);
    expect(logo.x).toBeGreaterThanOrEqual(0);
    expect(logo.size).toMatch(/^\d+px$/);
    const h1 = await page
      .getByRole("heading", { level: 1 })
      .evaluate((el) => getComputedStyle(el).fontFamily);
    expect(h1).toBe(logo.font);
  }
  if (isMobile) return;
  await page.setViewportSize({ width: 1440, height: 1000 });
  await page.emulateMedia({ reducedMotion: "no-preference" });
  const card = page.getByRole("article", { name: "Premium plan", exact: true });
  const button = card.getByRole("button", {
    name: "Upgrade to Premium",
    exact: true,
  });
  expect(
    await button.evaluate((el) => {
      const probe = document.createElement("span");
      probe.style.backgroundImage = "var(--upgrade-grad)";
      el.append(probe);
      const same =
        getComputedStyle(el).backgroundImage ===
        getComputedStyle(probe).backgroundImage;
      probe.remove();
      return same;
    }),
  ).toBe(true);
  await button.hover();
  await expect
    .poll(() => button.evaluate((el) => getComputedStyle(el).translate))
    .toBe("0px -2px");
  await expect
    .poll(() => card.evaluate((el) => getComputedStyle(el).translate))
    .toBe("none");
  await expect(button).toHaveCSS("filter", "none");
  expect(await button.evaluate((el) => getComputedStyle(el).boxShadow)).toBe(
    "none",
  );
  await page.emulateMedia({ reducedMotion: "reduce" });
  await expect
    .poll(() => button.evaluate((el) => getComputedStyle(el).translate))
    .toBe("none");
  await expect
    .poll(() => card.evaluate((el) => getComputedStyle(el).translate))
    .toBe("none");
});
